def merge_sorted(a, b):
    out, i, j = [], 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    return out + a[i:] + b[j:]

def max_profit(prices):
    best, low = 0, None
    for p in prices:
        if low is None or p < low:
            low = p
        best = max(best, p - low)
    return best

