def group_anagrams(words):
    groups = {}
    for w in words:
        key = "".join(sorted(w))
        groups.setdefault(key, []).append(w)
    return list(groups.values())

def average_by(records, group_key, value_key):
    totals, counts = {}, {}
    for r in records:
        g = r[group_key]
        totals[g] = totals.get(g, 0) + r[value_key]
        counts[g] = counts.get(g, 0) + 1
    return {g: round(totals[g] / counts[g], 1) for g in totals}

