def life_step(grid):
    rows, cols = len(grid), len(grid[0])
    new = [[0] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            n = 0
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    rr, cc = r + dr, c + dc
                    if (dr or dc) and 0 <= rr < rows and 0 <= cc < cols:
                        n += grid[rr][cc]
            if grid[r][c] == 1 and n in (2, 3):
                new[r][c] = 1
            elif grid[r][c] == 0 and n == 3:
                new[r][c] = 1
    return new

def rotate_cw(grid):
    rows, cols = len(grid), len(grid[0])
    return [[grid[rows - 1 - r][c] for r in range(rows)] for c in range(cols)]

def spiral(grid):
    out = []
    top, bottom, left, right = 0, len(grid) - 1, 0, len(grid[0]) - 1
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            out.append(grid[top][c])
        for r in range(top + 1, bottom + 1):
            out.append(grid[r][right])
        if top < bottom:
            for c in range(right - 1, left - 1, -1):
                out.append(grid[bottom][c])
        if left < right:
            for r in range(bottom - 1, top, -1):
                out.append(grid[r][left])
        top, bottom, left, right = top + 1, bottom - 1, left + 1, right - 1
    return out

DIRS = [("right", 0, 1), ("down", 1, 0), ("down-right", 1, 1), ("up-right", -1, 1),
        ("left", 0, -1), ("up", -1, 0), ("up-left", -1, -1), ("down-left", 1, -1)]

def find_word(grid, word):
    rows, cols = len(grid), len(grid[0])
    for r in range(rows):
        for c in range(cols):
            for name, dr, dc in DIRS:
                ok = True
                for i, ch in enumerate(word):
                    rr, cc = r + dr * i, c + dc * i
                    if not (0 <= rr < rows and 0 <= cc < cols) or grid[rr][cc] != ch:
                        ok = False
                        break
                if ok:
                    return (r, c, name)
    return None

def flood_count(grid, r, c):
    rows, cols = len(grid), len(grid[0])
    seen = set()
    todo = [(r, c)]
    while todo:
        rr, cc = todo.pop()
        if (rr, cc) in seen or not (0 <= rr < rows and 0 <= cc < cols) or grid[rr][cc] == "#":
            continue
        seen.add((rr, cc))
        todo += [(rr + 1, cc), (rr - 1, cc), (rr, cc + 1), (rr, cc - 1)]
    return len(seen)

