def tic_winner(board):
    lines = [board[r] for r in range(3)]
    lines += ["".join(board[r][c] for r in range(3)) for c in range(3)]
    lines.append("".join(board[i][i] for i in range(3)))
    lines.append("".join(board[i][2 - i] for i in range(3)))
    for line in lines:
        if line in ("XXX", "OOO"):
            return line[0]
    return None

def island_count(grid):
    rows, cols = len(grid), len(grid[0])
    seen = set()
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == "#" and (r, c) not in seen:
                count += 1
                todo = [(r, c)]
                while todo:
                    a, b = todo.pop()
                    if (a, b) in seen or not (0 <= a < rows and 0 <= b < cols) or grid[a][b] != "#":
                        continue
                    seen.add((a, b))
                    todo += [(a + 1, b), (a - 1, b), (a, b + 1), (a, b - 1)]
    return count

