import functools

def validate_positive(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        for a in args:
            if isinstance(a, (int, float)) and a < 0:
                raise ValueError(f"{fn.__name__} needs positive numbers, got {a}")
        return fn(*args, **kwargs)
    return wrapper

