from pathlib import Path

def dedupe(folder):
    seen, deleted = set(), []
    for p in sorted(Path(folder).iterdir()):
        data = p.read_bytes()
        if data in seen:
            p.unlink()
            deleted.append(p.name)
        else:
            seen.add(data)
    return deleted

