class Inventory:
    """Stock for a small shop. Each item: sku -> {"name", "qty", "price"}."""

    def __init__(self):
        self.items = {}

    def add(self, sku, name, qty, price):
        """Add new stock. Adding an existing sku tops up its quantity and updates the price."""
        if sku in self.items:
            self.items[sku]["qty"] += qty
            self.items[sku]["price"] = price
        else:
            self.items[sku] = {"name": name, "qty": qty, "price": price}

    def remove(self, sku, qty):
        """Take items out of stock (a sale). You can't sell what you don't have."""
        if sku not in self.items:
            raise KeyError(f"unknown sku {sku}")
        if qty > self.items[sku]["qty"]:
            raise ValueError("not enough stock")
        self.items[sku]["qty"] -= qty

    def low_stock(self, threshold=5):
        """SKUs with stock at or below the threshold, lowest first."""
        low = [sku for sku, item in self.items.items() if item["qty"] <= threshold]
        return sorted(low, key=lambda sku: self.items[sku]["qty"])

    def total_value(self):
        """What all the stock is worth."""
        total = 0
        for sku, item in self.items.items():
            total += item["qty"] * item["price"]
        return round(total, 2)

