def route(method, path):
    pattern = re.compile("^" + re.sub(r"<(\w+)>", r"(?P<\1>[^/]+)", path) + "$")

    def decorator(fn):
        ROUTES.append((method, pattern, fn))
        return fn
    return decorator

def match(method, path):
    for m, pattern, fn in ROUTES:
        found = pattern.match(path)
        if m == method and found:
            return fn, found.groupdict()
    return None

def handle(method, path, body=None):
    path, _, qs = path.partition("?")
    query = {k: v[0] for k, v in parse_qs(qs).items()}
    found = match(method, path)
    if found is None:
        if any(pattern.match(path) for _, pattern, _ in ROUTES):
            return 405, {"error": "method not allowed"}
        return 404, {"error": "not found"}
    fn, params = found
    try:
        result = fn({"params": params, "query": query, "body": body})
    except ValueError as e:
        return 400, {"error": str(e)}
    except Exception:
        return 500, {"error": "server error"}
    if isinstance(result, tuple):
        return result
    return 200, result

