def init_db():
    global DB
    DB = sqlite3.connect(":memory:")
    DB.row_factory = sqlite3.Row
    DB.execute("CREATE TABLE notes (id INTEGER PRIMARY KEY, text TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0)")

def note_dict(row):
    return {"id": row["id"], "text": row["text"], "done": bool(row["done"])}

def get_note(note_id):
    row = DB.execute("SELECT * FROM notes WHERE id = ?", (note_id,)).fetchone()
    return note_dict(row) if row else None

NOT_FOUND = (404, {"error": "note not found"})

@route("GET", "/notes")
def list_notes(req):
    q = req["query"].get("q")
    if q:
        rows = DB.execute("SELECT * FROM notes WHERE text LIKE ? ORDER BY id", (f"%{q}%",))
    else:
        rows = DB.execute("SELECT * FROM notes ORDER BY id")
    return [note_dict(r) for r in rows]

@route("POST", "/notes")
def create_note(req):
    text = ((req["body"] or {}).get("text") or "").strip()
    if not text:
        raise ValueError("text is required")
    with DB:
        cur = DB.execute("INSERT INTO notes (text) VALUES (?)", (text,))
    return 201, get_note(cur.lastrowid)

@route("GET", "/notes/<id>")
def read_note(req):
    note = get_note(int(req["params"]["id"]))
    return note if note else NOT_FOUND

@route("PATCH", "/notes/<id>")
def update_note(req):
    note_id = int(req["params"]["id"])
    if get_note(note_id) is None:
        return NOT_FOUND
    body = req["body"] or {}
    with DB:
        if "done" in body:
            DB.execute("UPDATE notes SET done = ? WHERE id = ?", (int(bool(body["done"])), note_id))
        if "text" in body:
            DB.execute("UPDATE notes SET text = ? WHERE id = ?", (body["text"], note_id))
    return get_note(note_id)

@route("DELETE", "/notes/<id>")
def delete_note(req):
    with DB:
        cur = DB.execute("DELETE FROM notes WHERE id = ?", (int(req["params"]["id"]),))
    return (204, None) if cur.rowcount else NOT_FOUND

