class Calc:
    def __init__(self):
        self.clear()

    def clear(self):
        self.current, self.stored, self.op, self.fresh = "0", None, None, True

    def digit(self, d):
        if self.fresh:
            self.current, self.fresh = d, False
        elif self.current == "0":
            self.current = d
        elif len(self.current.replace(".", "").replace("-", "")) < 12:
            self.current += d

    def dot(self):
        if self.fresh:
            self.current, self.fresh = "0.", False
        elif "." not in self.current:
            self.current += "."

def apply(a, op, b):
    if op == "+":
        return a + b
    if op == "−":
        return a - b
    if op == "×":
        return a * b
    if op == "÷":
        if b == 0:
            raise ZeroDivisionError
        return a / b
    return b

def _operator(self, op):
    if self.op is not None and not self.fresh:
        self.equals()
    if self.current == "Error":
        return
    self.stored = float(self.current)
    self.op = op
    self.fresh = True

def _equals(self):
    if self.op is None or self.stored is None:
        return
    try:
        result = apply(self.stored, self.op, float(self.current))
    except ZeroDivisionError:
        self.current, self.stored, self.op, self.fresh = "Error", None, None, True
        return
    self.current = repr(result)
    self.stored, self.op, self.fresh = None, None, True

Calc.operator = _operator
Calc.equals = _equals

