steps.solution:
def current_streak(h, today):
    day = today if today in h.done else today - timedelta(days=1)
    count = 0
    while day in h.done:
        count += 1
        day -= timedelta(days=1)
    return count

def best_streak(h):
    best = 0
    for d in h.done:
        if d - timedelta(days=1) not in h.done:
            length = 1
            while d + timedelta(days=length) in h.done:
                length += 1
            best = max(best, length)
    return best

def rate(h, today, days=7):
    hits = sum(1 for i in range(days) if today - timedelta(days=i) in h.done)
    return round(hits / days * 100)

