def heatmap(h, today, weeks=4):
    total = weeks * 7
    start = today - timedelta(days=total - 1)
    lines = []
    for w in range(weeks):
        cells = []
        for d in range(7):
            day = start + timedelta(days=w * 7 + d)
            cells.append("■" if day in h.done else "·")
        lines.append(" ".join(cells))
    return "\n".join(lines)

def summary(h, today):
    return f"🔥 {current_streak(h, today)} day streak · best {best_streak(h)} · {rate(h, today)}% this week"

