def find(maze, ch):
    for r, row in enumerate(maze):
        c = row.find(ch)
        if c != -1:
            return (r, c)
    return None

def neighbours(maze, cell):
    r, c = cell
    out = []
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        rr, cc = r + dr, c + dc
        if 0 <= rr < len(maze) and 0 <= cc < len(maze[0]) and maze[rr][cc] != "#":
            out.append((rr, cc))
    return out

def solve(maze, cell, goal, visited):
    if cell == goal:
        return [cell]
    visited.add(cell)
    for nxt in neighbours(maze, cell):
        if nxt not in visited:
            path = solve(maze, nxt, goal, visited)
            if path:
                return [cell] + path
    return None

