LOAN_DAYS = 14
MAX_BOOKS = 3


class Book:
    def __init__(self, isbn, title, copies):
        self.isbn, self.title, self.copies = isbn, title, copies


class Member:
    def __init__(self, member_id, name):
        self.id, self.name = member_id, name
        self.loans = {}  # isbn -> due date


class Library:
    def __init__(self):
        self.books = {}
        self.members = {}

    def add_book(self, isbn, title, copies=1):
        if isbn in self.books:
            self.books[isbn].copies += copies
        else:
            self.books[isbn] = Book(isbn, title, copies)

    def add_member(self, member_id, name):
        self.members[member_id] = Member(member_id, name)

    def _member(self, member_id):
        if member_id not in self.members:
            raise ValueError("unknown member")
        return self.members[member_id]

    def _book(self, isbn):
        if isbn not in self.books:
            raise ValueError("unknown book")
        return self.books[isbn]

    def available(self, isbn):
        book = self._book(isbn)
        lent = sum(isbn in m.loans for m in self.members.values())
        return book.copies - lent

    def checkout(self, member_id, isbn, day):
        member, book = self._member(member_id), self._book(isbn)
        if any(due < day for due in member.loans.values()):
            raise ValueError("has overdue books")
        if isbn in member.loans:
            raise ValueError("already borrowed")
        if len(member.loans) >= MAX_BOOKS:
            raise ValueError("limit reached")
        if self.available(isbn) <= 0:
            raise ValueError("no copies left")
        member.loans[isbn] = day + timedelta(days=LOAN_DAYS)
        return member.loans[isbn]

    def return_book(self, member_id, isbn):
        member = self._member(member_id)
        if isbn not in member.loans:
            raise ValueError("not borrowed")
        del member.loans[isbn]

    def books_of(self, member_id):
        member = self._member(member_id)
        return sorted(self.books[i].title for i in member.loans)

    def overdue(self, today):
        late = [(m.name, self.books[i].title) for m in self.members.values() for i, due in m.loans.items() if due < today]
        return sorted(late)

