import heapq

def to_min(t):
    h, m = t.split(":")
    return int(h) * 60 + int(m)

def to_hhmm(n):
    return f"{n // 60:02d}:{n % 60:02d}"

def rooms_needed(meetings):
    events = []
    for s, e in meetings:
        events.append((to_min(s), 1))
        events.append((to_min(e), -1))
    events.sort()
    cur = best = 0
    for _, d in events:
        cur += d
        best = max(best, cur)
    return best

def assign_rooms(meetings):
    order = sorted(range(len(meetings)), key=lambda i: (to_min(meetings[i][0]), i))
    free = []
    busy = []
    next_room = 1
    out = [0] * len(meetings)
    for i in order:
        s, e = to_min(meetings[i][0]), to_min(meetings[i][1])
        while busy and busy[0][0] <= s:
            _, room = heapq.heappop(busy)
            heapq.heappush(free, room)
        if free:
            room = heapq.heappop(free)
        else:
            room = next_room
            next_room += 1
        out[i] = room
        heapq.heappush(busy, (e, room))
    return out

def common_free(calendars, day_start="09:00", day_end="17:00", length=30):
    busy = sorted((to_min(s), to_min(e)) for cal in calendars for s, e in cal)
    merged = []
    for s, e in busy:
        if merged and s <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    free = []
    cur = to_min(day_start)
    end = to_min(day_end)
    for s, e in merged:
        if s > cur:
            free.append((cur, min(s, end)))
        cur = max(cur, e)
    if cur < end:
        free.append((cur, end))
    return [(to_hhmm(s), to_hhmm(e)) for s, e in free if e - s >= length]

