import csv

RULES = {
    "income": ["PAYROLL", "REFUND"],
    "housing": ["RENT"],
    "groceries": ["WHOLE FOODS", "TRADER JOE"],
    "transport": ["UBER", "SHELL"],
    "dining": ["STARBUCKS", "CHIPOTLE"],
    "subscriptions": ["NETFLIX", "SPOTIFY"],
}

def load(path):
    with open(path, newline="") as f:
        return [{"date": r["date"], "description": r["description"], "amount": float(r["amount"])}
                for r in csv.DictReader(f)]

def categorize(description):
    text = description.upper()
    for category, words in RULES.items():
        if any(w in text for w in words):
            return category
    return "other"

def monthly(rows):
    totals = {}
    for r in rows:
        m = totals.setdefault(r["date"][:7], {"in": 0.0, "out": 0.0})
        if r["amount"] >= 0:
            m["in"] += r["amount"]
        else:
            m["out"] -= r["amount"]
    return {k: {"in": round(v["in"], 2), "out": round(v["out"], 2), "net": round(v["in"] - v["out"], 2)}
            for k, v in sorted(totals.items())}

def spending_by_category(rows):
    totals = {}
    for r in rows:
        if r["amount"] < 0:
            c = categorize(r["description"])
            totals[c] = totals.get(c, 0) - r["amount"]
    return sorted(((c, round(t, 2)) for c, t in totals.items()), key=lambda ct: (-ct[1], ct[0]))

def report(path):
    rows = load(path)
    months = monthly(rows)
    keys = list(months)
    print(f"Statement: {keys[0]} to {keys[-1]}")
    for k, m in months.items():
        print(f"{k}  in {m['in']:8.2f}  out {m['out']:8.2f}  net {m['net']:8.2f}")
    print("Spending by category:")
    for c, t in spending_by_category(rows):
        print(f"  {c:<14}{t:8.2f}")
    spending = [r for r in rows if r["amount"] < 0 and categorize(r["description"]) != "housing"]
    big = min(spending, key=lambda r: r["amount"])
    print(f"Largest purchase (not housing): {big['description']} on {big['date']}, {-big['amount']:.2f}")

report("statement.csv")

ANSWER = "PLANT"

def score(guess, answer):
    guess, answer = guess.upper(), answer.upper()
    result = ["."] * 5
    left = {}
    for i in range(5):
        if guess[i] == answer[i]:
            result[i] = "G"
        else:
            left[answer[i]] = left.get(answer[i], 0) + 1
    for i in range(5):
        if result[i] == "." and left.get(guess[i], 0) > 0:
            result[i] = "Y"
            left[guess[i]] -= 1
    return "".join(result)

def play(answer, max_tries=6):
    tries = 0
    while tries < max_tries:
        guess = input("Guess: ").strip().upper()
        if len(guess) != 5 or not guess.isalpha():
            print("Guesses must be 5 letters.")
            continue
        tries += 1
        print(guess, score(guess, answer))
        if guess == answer:
            print(f"Solved in {tries}!")
            return tries
    print(f"Out of guesses. The word was {answer}.")

play(ANSWER)

